use std::fmt;
use std::path::PathBuf;
use std::str::FromStr;
use strum::IntoEnumIterator;
use uuid::Uuid;

#[derive(Debug, Clone, PartialEq, Eq)]
struct DID(DIDKey);
#[derive(Debug, Clone, PartialEq, Eq)]
struct DIDKey;
impl Default for DID {
    fn default() -> Self {
        DID(DIDKey)
    }
}
impl fmt::Display for DID {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("did:example")
    }
}
impl FromStr for DID {
    type Err = std::io::Error;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Ok(DID(DIDKey))
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ReactionState;
impl ReactionState {
    const Add: ReactionState = ReactionState;
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MessageOptions;
impl Default for MessageOptions {
    fn default() -> Self {
        MessageOptions
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Location;

#[derive(Debug, derive_more::Display, strum_macros::EnumIter)]
enum Command {
    #[display(fmt = "/create <did> - create conversation with another user")]
    CreateConversation(DID),
    #[display(fmt = "/add-recipient <did> - add recipient to conversation")]
    AddRecipient(DID),
    #[display(fmt = "/remove-recipient <did> - remove recipient from conversation")]
    RemoveRecipient(DID),
    #[display(fmt = "/create-group <name> <did> ... - create group conversation with other users")]
    CreateGroupConversation(String, Vec<DID>),
    #[display(
        fmt = "/remove-conversation <conversation-id> - delete current conversation. This will delete it on both ends"
    )]
    RemoveConversation(Uuid),
    #[display(fmt = "/set-conversation <id> - switch to a conversation")]
    SetConversation(Uuid),
    #[display(fmt = "/set-conversation-name <name> - set conversation name")]
    SetConversationName(String),
    #[display(fmt = "/list-conversations - list all active conversations")]
    ListConversations,
    #[display(fmt = "/list-references <lower-range> <upper-range> - list all message references in the conversation")]
    ListReferences(MessageOptions),
    #[display(fmt = "/list <lower-range> <upper-range> - list all messages in the conversation. This provides more info")]
    ListMessages(MessageOptions),
    #[display(fmt = "/list-pages <page> <amount> - list pages of messages in the conversation")]
    ListPages(MessageOptions),
    #[display(fmt = "/remove-message <message-id> - remove message from conversation")]
    RemoveMessage(Uuid),
    #[display(fmt = "/get-first - get first message in conversation")]
    GetFirst,
    #[display(fmt = "/get-last - get last message in conversation")]
    GetLast,
    #[display(fmt = "/search <keywords> ... - search for messages in conversation")]
    Search(String),
    #[display(fmt = "/edit <message-id> <message> - edit message in the conversation")]
    EditMessage(Uuid, String),
    #[display(fmt = "/attach <path> ... - attach files to the conversation")]
    Attach(Vec<Location>),
    #[display(fmt = "/download <message-id> <name> <path> - download file from conversation")]
    Download(Uuid, String, PathBuf),
    #[strum(disabled)]
    #[display(fmt = "/react <message-id> <add | remove> <emoji> - add or remove reaction to a message")]
    React(Uuid, ReactionState, String),
    #[display(fmt = "/status <message-id> - get message status")]
    Status(Uuid),
    #[display(fmt = "/pin <all | message-id> - pin a message in the conversation.")]
    Pin(PinTarget),
    #[display(fmt = "/unpin <all | message-id> - unpin a message in the conversation.")]
    Unpin(PinTarget),
    #[display(fmt = "/count-messages - count messages in the conversation")]
    CountMessages,
}

#[derive(Debug, Default)]
enum PinTarget {
    #[default]
    All,
    Message(Uuid),
}

fn list_commands_and_help() -> String {
    let mut help = String::from("List of all commands:\n");
    for cmd in Command::iter() {
        help.push('\t');
        help.push_str(cmd.to_string().as_str());
        help.push('\n');
    }
    help.push('\t');
    help.push_str(
        Command::React(Uuid::nil(), ReactionState::Add, String::new())
            .to_string()
            .as_str(),
    );
    help.push('\n');
    help
}

fn main() {
    let help = list_commands_and_help();
    println!("{}", help);
    let lines: Vec<&str> = help.lines().skip(1).collect();
    assert_eq!(lines.len(), 22, "expected 22 commands, got {}", lines.len());
    let required = [
        "/create",
        "/add-recipient",
        "/remove-recipient",
        "/create-group",
        "/remove-conversation",
        "/set-conversation",
        "/set-conversation-name",
        "/list-conversations",
        "/list-references",
        "/list ",
        "/list-pages",
        "/remove-message",
        "/get-first",
        "/get-last",
        "/search",
        "/edit",
        "/attach",
        "/download",
        "/react",
        "/status",
        "/pin",
        "/unpin",
        "/count-messages",
    ];
    let joined = lines.join("\n");
    for r in required {
        assert!(
            joined.contains(r),
            "missing command entry containing {} in help:\n{}",
            r,
            help
        );
    }
    eprintln!("VERIFY OK: all 22 commands present in help output");
}

