struct TesseractInner {
    enc_pass: Arc<RwLock<Vec<u8>>>,
    unlock: Arc<AtomicBool>,
    soft_unlock: Arc<AtomicBool>,
    event_tx: Sender<TesseractEvent>,
    event_rx: async_broadcast::Receiver<TesseractEvent>,
}

impl Default for Tesseract {
    fn default() -> Self {
        let (mut event_tx, event_rx) = async_broadcast::broadcast(1);
        event_tx.set_overflow(true);
        Tesseract {
            inner: Arc::new(TesseractInner {
                enc_pass: Arc::new(RwLock::new(Vec::new())),
                unlock: Arc::new(AtomicBool::new(false)),
                soft_unlock: Arc::new(AtomicBool::new(false)),
                event_tx,
                event_rx,
            }),
        }
    }
}

impl Drop for TesseractInner {
    fn drop(&mut self) {
        if !self.enc_pass.read().unwrap().is_empty()
            && self.unlock.load(Ordering::Relaxed)
            && !self.soft_unlock.load(Ordering::Relaxed)
        {
            self.enc_pass.write().unwrap().fill(0);
            self.unlock.store(false, Ordering::Relaxed);
            self.soft_unlock.store(false, Ordering::Relaxed);
            let _ = self.event_tx.try_broadcast(TesseractEvent::Locked);
        }
    }
}

impl Tesseract {
    pub fn is_unlock(&self) -> bool {
        !self.inner.enc_pass.read().unwrap().is_empty()
            && self.inner.unlock.load(Ordering::Relaxed)
            && !self.inner.soft_unlock.load(Ordering::Relaxed)
    }

    pub fn unlock(&self, passphrase: &[u8]) {
        *self.inner.enc_pass.write().unwrap() = passphrase.to_vec();
        self.inner.unlock.store(true, Ordering::Relaxed);
        let _ = self.inner.event_tx.try_broadcast(TesseractEvent::Unlocked);
    }

    pub fn lock(&self) {
        self.inner.enc_pass.write().unwrap().fill(0);
        self.inner.unlock.store(false, Ordering::Relaxed);
        self.inner.soft_unlock.store(false, Ordering::Relaxed);
        let _ = self.inner.event_tx.try_broadcast(TesseractEvent::Locked);
    }

    pub fn subscribe(&self) -> BoxStream<'static, TesseractEvent> {
        let mut rx = self.inner.event_rx.clone();
        let stream = async_stream::stream! {
            loop {
                match rx.recv().await {
                    Ok(event) => yield event,
                    Err(async_broadcast::RecvError::Closed) => break,
                    Err(_) => {}
                };
            }
        };
        stream.boxed()
    }
}

