use std::{
    collections::BTreeMap,
    ffi::OsStr,
    fmt::Display,
    hash::Hash,
    io::{self, ErrorKind},
    path::{Path, PathBuf},
    sync::{
        atomic::{AtomicUsize, Ordering},
        Arc,
    },
    time::Instant,
};

use futures::stream;
use futures::StreamExt;
use image::io::Reader as ImageReader;
use image::ImageFormat;
use rust_ipfs::unixfs::AddOption;
use rust_ipfs::{Ipfs, IpfsPath};
use tokio::sync::Mutex;
use tokio::task::JoinHandle;
use warp::{constellation::file::FileType, error::Error};

use crate::store::document::image_dag::ImageDag;
use crate::utils::ExtensionType;

static GLOBAL_ID: AtomicUsize = AtomicUsize::new(0);

#[derive(Debug, Copy, Clone, Hash, PartialEq, Eq, PartialOrd, Ord)]
pub struct ThumbnailId(usize);

impl Display for ThumbnailId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl core::ops::Deref for ThumbnailId {
    type Target = usize;
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl Default for ThumbnailId {
    fn default() -> Self {
        ThumbnailId(GLOBAL_ID.fetch_add(1, Ordering::SeqCst))
    }
}

#[derive(Clone)]
#[allow(clippy::type_complexity)]
pub struct ThumbnailGenerator {
    ipfs: Ipfs,
    tasks: Arc<
        Mutex<BTreeMap<ThumbnailId, JoinHandle<Result<(ExtensionType, IpfsPath, Vec<u8>), Error>>>>,
    >,
}

impl ThumbnailGenerator {
    pub fn new(ipfs: Ipfs) -> Self {
        ThumbnailGenerator {
            ipfs,
            tasks: Arc::default(),
        }
    }

    pub async fn insert<P: AsRef<Path>>(
        &self,
        path: P,
        width: u32,
        height: u32,
        output_exact: bool,
    ) -> Result<ThumbnailId, Error> {
        let path = path.as_ref();
        if !path.is_file() {
            return Err(io::Error::from(ErrorKind::NotFound).into());
        }

        let own_path = path.to_path_buf();
        let id = ThumbnailId::default();
        let ipfs = self.ipfs.clone();

        let task = tokio::spawn(async move {
            let instance = Instant::now();
            //TODO: Read file header to determine real file type for anything like images, videos and documents.
            let extension = own_path
                .extension()
                .and_then(OsStr::to_str)
                .map(ExtensionType::from)
                .unwrap_or(ExtensionType::Other);

            let result = match extension.into() {
                FileType::Mime(media) => match media.ty().as_str() {
                    "image" => tokio::task::spawn_blocking(move || {
                        let format: ImageFormat = extension.try_into()?;
                        let image = image::open(own_path).map_err(anyhow::Error::from)?;
                        let width = width.min(image.width());
                        let height = height.min(image.height());

                        let thumbnail = image.thumbnail(width, height);

                        let mut t_buffer = std::io::Cursor::new(vec![]);
                        let output_format = match (output_exact, format) {
                            (false, _) => ImageFormat::Jpeg,
                            (true, ImageFormat::WebP) if cfg!(not(feature = "webp")) => {
                                ImageFormat::Jpeg
                            }
                            (true, format) => format,
                        };

                        thumbnail
                            .write_to(&mut t_buffer, output_format)
                            .map_err(anyhow::Error::from)?;
                        Ok::<_, Error>((
                            ExtensionType::try_from(output_format)?,
                            t_buffer.into_inner(),
                        ))
                    })
                    .await
                    .map_err(anyhow::Error::from)?,
                    _ => Err(Error::Unimplemented),
                },
                _ => Err(Error::Other),
            };

            let result = match result {
                Ok((extension_type, thumbnail)) => {
                    let stream = stream::once(async move {
                        Ok::<_, std::io::Error>(thumbnail.clone())
                    })
                    .boxed();

                    let path = ipfs
                        .unixfs()
                        .add(
                            stream,
                            Some(AddOption {
                                pin: true,
                                ..Default::default()
                            }),
                        )
                        .await?;

                    let cid = path
                        .root()
                        .cid()
                        .copied()
                        .ok_or(Error::OtherWithContext("unable to get cid".into()))?;

                    let image_dag = ImageDag {
                        link: cid,
                        size: thumbnail.len() as _,
                        mime: extension_type.into(),
                    };

                    let cid = ipfs
                        .dag()
                        .put()
                        .serialize(image_dag)?
                        .pin(true)
                        .await?;

                    Ok((extension_type, IpfsPath::from(cid), thumbnail))
                }
                Err(e) => Err(e),
            };

            let stop = instance.elapsed();

            tracing::trace!("Took: {}ms to complete task for {}", stop.as_millis(), id);
            result
        });

        self.tasks.lock().await.insert(id, task);

        Ok(id)
    }

    pub async fn insert_buffer<S: AsRef<str>>(
        &self,
        name: S,
        buffer: &[u8],
        width: u32,
        height: u32,
        output_exact: bool,
    ) -> ThumbnailId {
        let name = PathBuf::from(name.as_ref());

        let buffer = std::io::Cursor::new(buffer.to_vec());

        let id = ThumbnailId::default();
        let ipfs = self.ipfs.clone();

        let task = tokio::spawn(async move {
            let instance = Instant::now();

            let extension = name
                .extension()
                .and_then(OsStr::to_str)
                .map(ExtensionType::from)
                .unwrap_or(ExtensionType::Other);

            let result = match extension.into() {
                FileType::Mime(media) => match media.ty().as_str() {
                    "image" => tokio::task::spawn_blocking(move || {
                        let format: ImageFormat = extension.try_into()?;
                        let image = ImageReader::new(buffer)
                            .with_guessed_format()?
                            .decode()
                            .map_err(anyhow::Error::from)?;

                        let width = width.min(image.width());
                        let height = height.min(image.height());

                        let thumbnail = image.thumbnail(width, height);
                        let mut t_buffer = std::io::Cursor::new(vec![]);
                        let output_format = match (output_exact, format) {
                            (false, _) => ImageFormat::Jpeg,
                            (true, ImageFormat::WebP) if cfg!(not(feature = "webp")) => {
                                ImageFormat::Jpeg
                            }
                            (true, format) => format,
                        };
                        thumbnail
                            .write_to(&mut t_buffer, output_format)
                            .map_err(anyhow::Error::from)?;
                        Ok::<_, Error>((
                            ExtensionType::try_from(output_format)?,
                            t_buffer.into_inner(),
                        ))
                    })
                    .await
                    .map_err(anyhow::Error::from)?,
                    _ => Err(Error::Unimplemented),
                },
                _ => Err(Error::Other),
            };

            let result = match result {
                Ok((extension_type, thumbnail)) => {
                    let stream = stream::once(async move {
                        Ok::<_, std::io::Error>(thumbnail.clone())
                    })
                    .boxed();

                    let path = ipfs
                        .unixfs()
                        .add(
                            stream,
                            Some(AddOption {
                                pin: true,
                                ..Default::default()
                            }),
                        )
                        .await?;

                    let cid = path
                        .root()
                        .cid()
                        .copied()
                        .ok_or(Error::OtherWithContext("unable to get cid".into()))?;

                    let image_dag = ImageDag {
                        link: cid,
                        size: thumbnail.len() as _,
                        mime: extension_type.into(),
                    };

                    let cid = ipfs
                        .dag()
                        .put()
                        .serialize(image_dag)?
                        .pin(true)
                        .await?;

                    Ok((extension_type, IpfsPath::from(cid), thumbnail))
                }
                Err(e) => Err(e),
            };

            let stop = instance.elapsed();

            tracing::trace!("Took: {}ms to complete task for {}", stop.as_millis(), id);
            result
        });

        self.tasks.lock().await.insert(id, task);

        id
    }

    #[allow(dead_code)]
    pub async fn cancel(&self, id: ThumbnailId) {
        let task = self.tasks.lock().await.remove(&id);
        if let Some(task) = task {
            task.abort();
        }
    }

    pub async fn get(&self, id: ThumbnailId) -> Result<(ExtensionType, IpfsPath, Vec<u8>), Error> {
        let task = self.tasks.lock().await.remove(&id);
        let task = task.ok_or(Error::Other)?;
        task.await.map_err(anyhow::Error::from)?
    }

    #[allow(dead_code)]
    pub async fn is_finished(&self, id: ThumbnailId) -> Result<bool, Error> {
        if let Some(task) = self.tasks.lock().await.get(&id) {
            return Ok(task.is_finished());
        }
        Err(Error::Other)
    }
}

use std::{collections::BTreeMap, str::FromStr};

use async_recursion::async_recursion;
use chrono::{DateTime, Utc};
use libipld::Cid;
use rust_ipfs::{Ipfs, IpfsPath};
use serde::{Deserialize, Serialize};
use warp::{
    constellation::{
        directory::Directory,
        file::{File, FileType},
        item::Item,
    },
    error::Error,
};

#[derive(Deserialize, Serialize, Debug, Clone)]
pub struct FileDocument {
    pub name: String,
    pub size: usize,
    pub description: String,
    pub favorite: bool,
    pub file_type: FileType,
    pub creation: DateTime<Utc>,
    pub modified: DateTime<Utc>,
    pub thumbnail: Option<Cid>,
    pub reference: String,
}

impl FileDocument {
    pub async fn new(ipfs: &Ipfs, file: &File) -> Result<Self, Error> {
        let mut document = FileDocument {
            name: file.name(),
            size: file.size(),
            description: file.description(),
            favorite: file.favorite(),
            file_type: file.file_type(),
            creation: file.creation(),
            modified: file.modified(),
            thumbnail: None,
            reference: file.reference().ok_or(Error::Other)?,
        };

        if let Some(reference) = file.thumbnail_reference() {
            document.thumbnail = cid_from_path(&reference);
        }

        let _ = ipfs;
        Ok(document)
    }

    pub async fn put(&self, ipfs: &Ipfs) -> Result<Cid, Error> {
        let cid = ipfs.dag().put().serialize(self)?.await?;
        Ok(cid)
    }

    pub async fn get(ipfs: &Ipfs, cid: Cid) -> Result<Self, Error> {
        let document = ipfs.get_dag(cid).local().deserialized().await?;
        Ok(document)
    }

    pub async fn resolve(&self, ipfs: &Ipfs) -> Result<File, Error> {
        let file = File::new(&self.name);
        file.set_size(self.size);
        file.set_description(&self.description);
        file.set_favorite(self.favorite);
        file.set_creation(Some(self.creation));
        file.set_modified(Some(self.modified));
        file.set_file_type(self.file_type);
        file.set_reference(&self.reference);

        if let Some(thumbnail) = self.thumbnail {
            file.set_thumbnail_reference(&thumbnail.to_string());
        }

        let _ = ipfs;
        Ok(file)
    }
}

#[derive(Deserialize, Serialize, Debug, Clone)]
pub struct DirectoryDocument {
    pub name: String,
    pub description: String,
    pub favorite: bool,
    pub creation: DateTime<Utc>,
    pub modified: DateTime<Utc>,
    pub thumbnail: Option<Cid>,
    pub items: Option<Cid>,
}

impl DirectoryDocument {
    #[async_recursion]
    pub async fn new(ipfs: &Ipfs, directory: &Directory) -> Result<Self, Error> {
        let mut document = DirectoryDocument {
            name: directory.name(),
            description: directory.description(),
            favorite: directory.favorite(),
            creation: directory.creation(),
            modified: directory.modified(),
            thumbnail: None,
            items: None,
        };

        if let Some(reference) = directory.thumbnail_reference() {
            document.thumbnail = cid_from_path(&reference);
        }

        let mut items: BTreeMap<String, Cid> = BTreeMap::new();

        for item in directory.get_items() {
            let document = ItemDocument::new(ipfs, &item).await?;
            let cid = document.put(ipfs).await?;
            items.insert(item.name(), cid);
        }

