use libipld::Cid;
use rust_ipfs::UninitializedIpfsNoop;
use warp::constellation::{
    directory::Directory,
    file::File,
    item::{FormatType, Item},
};

use super::{DirectoryDocument, FileDocument, ItemDocument};

#[tokio::test]
async fn file_document_roundtrip() -> anyhow::Result<()> {
    let ipfs = UninitializedIpfsNoop::new().start().await?;

    let file = File::new("test.txt");
    file.set_size(123);
    file.set_description("a test file");
    file.set_favorite(true);
    file.set_reference("/ipfs/QmYwAPJzv5CZsnAzt8auVZRnKjxZ2K2tg6iN7bTfCJnGMD");
    file.set_thumbnail_reference("/ipfs/QmYwAPJzv5CZsnAzt8auVZRnKjxZ2K2tg6iN7bTfCJnGMD");
    file.set_thumbnail_format(FormatType::Mime(
        "image/png".parse::<mediatype::MediaTypeBuf>().unwrap(),
    ));

    let document = FileDocument::new(&ipfs, &file).await?;
    let cid: Cid = document.put(&ipfs).await?;
    let fetched = FileDocument::get(&ipfs, cid).await?;
    let resolved = fetched.resolve(&ipfs).await?;

    assert_eq!(resolved.name(), file.name());
    assert_eq!(resolved.size(), file.size());
    assert_eq!(resolved.description(), file.description());
    assert_eq!(resolved.favorite(), file.favorite());
    assert_eq!(resolved.reference(), file.reference());
    assert_eq!(resolved.thumbnail_reference(), file.thumbnail_reference());

    Ok(())
}

#[tokio::test]
async fn directory_document_roundtrip() -> anyhow::Result<()> {
    let ipfs = UninitializedIpfsNoop::new().start().await?;

    let mut root = Directory::new("root");
    let mut sub = Directory::new("sub");
    let mut sub_sub = Directory::new("sub_sub");

    let file_a = File::new("a.txt");
    file_a.set_reference("/ipfs/QmYwAPJzv5CZsnAzt8auVZRnKjxZ2K2tg6iN7bTfCJnGMD");
    file_a.set_thumbnail_reference("/ipfs/QmYwAPJzv5CZsnAzt8auVZRnKjxZ2K2tg6iN7bTfCJnGMD");

    let file_b = File::new("b.txt");
    file_b.set_reference("/ipfs/QmYwAPJzv5CZsnAzt8auVZRnKjxZ2K2tg6iN7bTfCJnGMD");

    sub_sub.add_item(file_a)?;
    sub.add_item(sub_sub)?;
    sub.add_item(file_b)?;
    root.add_item(sub)?;

    let document = DirectoryDocument::new(&ipfs, &root).await?;
    let cid: Cid = document.put(&ipfs).await?;
    let fetched = DirectoryDocument::get(&ipfs, cid).await?;
    let resolved = fetched.resolve(&ipfs).await?;

    assert_eq!(resolved.name(), root.name());
    assert!(resolved.has_item("sub"));
    assert!(resolved
        .get_item("sub")
        .unwrap()
        .get_directory()
        .unwrap()
        .has_item("sub_sub"));

    Ok(())
}

#[tokio::test]
async fn item_document_roundtrip() -> anyhow::Result<()> {
    let ipfs = UninitializedIpfsNoop::new().start().await?;

    let file = File::new("test.txt");
    file.set_size(123);
    file.set_reference("/ipfs/QmYwAPJzv5CZsnAzt8auVZRnKjxZ2K2tg6iN7bTfCJnGMD");
    file.set_thumbnail_reference("/ipfs/QmYwAPJzv5CZsnAzt8auVZRnKjxZ2K2tg6iN7bTfCJnGMD");

    let item = Item::new_file(file);

    let document = ItemDocument::new(&ipfs, &item).await?;
    let cid: Cid = document.put(&ipfs).await?;
    let fetched = ItemDocument::get(&ipfs, cid).await?;

    match fetched {
        ItemDocument::File(document) => {
            assert_eq!(document.name, "test.txt");
            assert_eq!(document.size, 123);
        }
