use crate::thumbnail::ThumbnailGenerator;
use rust_ipfs::UninitializedIpfsNoop;

#[tokio::test]
async fn thumbnail_generator_stores_to_ipfs() -> anyhow::Result<()> {
    let ipfs = UninitializedIpfsNoop::new().start().await?;

    let generator = ThumbnailGenerator::new(ipfs);

    let file = std::env::temp_dir().join("warp_thumbnail_test.png");

    let width = 8u32;
    let height = 8u32;

    let mut image =
        image::RgbaImage::from_pixel(width, height, image::Rgba([255u8, 0, 0, 255]));
    for y in 0..height {
        for x in 0..width {
            if (x + y) % 2 == 0 {
                image.put_pixel(x, y, image::Rgba([0, 255, 0, 255]));
            }
        }
    }
    image.save(&file)?;

    let ticket = generator
        .insert(&file, width, height, false)
        .await
        .expect("inserted");
    let (extension_type, ipfs_path, thumbnail_data) = generator.get(ticket).await?;

    assert!(!thumbnail_data.is_empty());
    assert!(ipfs_path.to_string().contains("/ipfs/"));

    let _ = std::fs::remove_file(&file);
    let _ = extension_type;
    let _ = image::make_rgba_image;
    Ok(())
}

#[tokio::test]
async fn thumbnail_generator_insert_buffer() -> anyhow::Result<()> {
    let ipfs = UninitializedIpfsNoop::new().start().await?;

    let generator = ThumbnailGenerator::new(ipfs);

    let mut cursor = std::io::Cursor::new(vec![]);
    let img = image::DynamicImage::new_rgba8(8, 8);
    img.write_to(&mut cursor, image::ImageFormat::Png)?;
    let buffer = cursor.into_inner();

    let ticket = generator
        .insert_buffer("test.png", &buffer, 8, 8, false)
        .await;

    let (extension_type, ipfs_path, thumbnail_data) = generator.get(ticket).await?;

    assert!(!thumbnail_data.is_empty());
    assert!(ipfs_path.to_string().contains("/ipfs/"));

    let _ = extension_type;
    Ok(())
}

